{
  "decisions": [
    {
      "requirement_id": "AI-001",
      "methods": ["Test"],
      "rationale": "The classification result and confidence score can be observed directly by executing the service with sample documents."
    },
    {
      "requirement_id": "AI-002",
      "methods": ["Analiz"],
      "rationale": "Achieving a macro‑averaged F1 score requires statistical analysis of model predictions on a held‑out set."
    },
    {
      "requirement_id": "AI-003",
      "methods": ["Test"],
      "rationale": "Routing low‑confidence documents to a human queue can be verified by running the service and inspecting the routing behavior."
    },
    {
      "requirement_id": "AI-004",
      "methods": ["Test"],
      "rationale": "Response time for the 95th percentile can be measured by executing the service under the specified load."
    },
    {
      "requirement_id": "AI-005",
      "methods": ["Test"],
      "rationale": "Recording of model version, input hash, and predicted category is observable in the service logs during execution."
    },
    {
      "requirement_id": "AI-006",
      "methods": ["Analiz"],
      "rationale": "Detecting a population stability index > 0.2 requires statistical analysis of weekly category distributions."
    },
    {
      "requirement_id": "AI-007",
      "methods": ["Test"],
      "rationale": "The three contributing text passages are part of the service output and can be verified by running the service."
    },
    {
      "requirement_id": "AI-008",
      "methods": ["Analiz"],
      "rationale": "Comparing recall across Turkish and English documents involves analytical evaluation of model performance per language."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KK-001",
      "methods": ["Test"],
      "rationale": "The requirement can be verified by executing the software, providing sensor updates, and observing that the map is updated within 1 second."
    },
    {
      "requirement_id": "KK-002",
      "methods": ["Test"],
      "rationale": "Performance under load can be validated by running the system with 2,000 tracks and measuring the refresh rate to ensure it stays above 10 Hz."
    },
    {
      "requirement_id": "KK-003",
      "methods": ["Test"],
      "rationale": "The operator’s ability to view track details is observable by interacting with the UI and confirming the displayed information."
    },
    {
      "requirement_id": "KK-004",
      "methods": ["Test"],
      "rationale": "The marking of stale tracks and their removal can be verified by observing the system behavior over the specified time intervals."
    },
    {
      "requirement_id": "KK-005",
      "methods": ["Test"],
      "rationale": "Visual and audible alerts can be confirmed by triggering a track entry into a defined area and observing the alerts."
    },
    {
      "requirement_id": "KK-006",
      "methods": ["Test"],
      "rationale": "Message delivery timing and status display can be validated by sending messages and measuring the elapsed time to receipt."
    },
    {
      "requirement_id": "KK-007",
      "methods": ["İnceleme"],
      "rationale": "Immutable logging requires inspection of the code and log records to ensure timestamps and user IDs are recorded in a tamper‑proof manner."
    },
    {
      "requirement_id": "KK-008",
      "methods": ["Test"],
      "rationale": "Failover can be verified by inducing primary server failure and observing that the backup assumes control within 10 seconds without data loss."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": ["Test"],
      "rationale": "The rejection of requests without a valid OAuth 2.0 token can be observed by sending such requests and verifying the HTTP 401 response."
    },
    {
      "requirement_id": "SW-002",
      "methods": ["Test"],
      "rationale": "Role‑based access enforcement can be validated by invoking endpoints with clients of different roles and checking for HTTP 403 when access is not permitted."
    },
    {
      "requirement_id": "SW-003",
      "methods": ["Test"],
      "rationale": "Rate‑limit behavior is observable by generating more than 600 requests per minute per client and confirming HTTP 429 with a Retry‑After header."
    },
    {
      "requirement_id": "SW-004",
      "methods": ["Test"],
      "rationale": "Latency at the 99th percentile under a 2,000 RPS load can be measured with performance testing tools and compared to the 20 ms limit."
    },
    {
      "requirement_id": "SW-005",
      "methods": ["Test"],
      "rationale": "The gateway’s timeout handling can be verified by causing the backend to exceed 5 seconds and observing the HTTP 504 response."
    },
    {
      "requirement_id": "SW-006",
      "methods": ["Test"],
      "rationale": "Dynamic configuration without restart can be validated by applying configuration changes while the gateway processes requests and confirming continuity of service."
    },
    {
      "requirement_id": "SW-007",
      "methods": ["İnceleme"],
      "rationale": "The required log entries can be inspected in the generated log files to ensure they contain the specified fields."
    },
    {
      "requirement_id": "SW-008",
      "methods": ["Analiz"],
      "rationale": "Monthly availability is a statistical metric that must be calculated from operational data over time."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "MED-001",
      "methods": ["Test"],
      "rationale": "The creation of a casualty record can be verified by executing the application, providing input, and observing the resulting record."
    },
    {
      "requirement_id": "MED-002",
      "methods": ["Test"],
      "rationale": "The distinct colour display for each triage category can be confirmed by running the UI and visually inspecting the colours."
    },
    {
      "requirement_id": "MED-003",
      "methods": ["Test"],
      "rationale": "Input validation and timestamping are observable behaviours that can be exercised with in‑range and out‑of‑range values."
    },
    {
      "requirement_id": "MED-004",
      "methods": ["Test"],
      "rationale": "Offline operation and the ability to store 500 records can be demonstrated by disabling network access and inserting records until the limit is reached."
    },
    {
      "requirement_id": "MED-005",
      "methods": ["Test"],
      "rationale": "Synchronization and conflict‑resolution logic are verified by restoring connectivity, performing a sync, and checking that both versions are retained for review."
    },
    {
      "requirement_id": "MED-006",
      "methods": ["İnceleme"],
      "rationale": "Encryption implementation is validated by reviewing the code and configuration to ensure AES‑256 is used correctly."
    },
    {
      "requirement_id": "MED-007",
      "methods": ["Test"],
      "rationale": "Operability with surgical gloves is a usability property that can be confirmed by having a user interact with the tablet while wearing gloves."
    },
    {
      "requirement_id": "MED-008",
      "methods": ["Test"],
      "rationale": "Battery endurance is measured by running the defined usage profile and timing how long the tablet remains powered."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": ["Test"],
      "rationale": "The ability to log in with e-Devlet credentials can be observed by executing the system and providing valid/invalid credentials."
    },
    {
      "requirement_id": "KMU-002",
      "methods": ["Test"],
      "rationale": "Session timeout behavior is observable by running the system, remaining idle for 15 minutes, and verifying redirection to the login page."
    },
    {
      "requirement_id": "KMU-003",
      "methods": ["Test"],
      "rationale": "The lockout after five consecutive failed login attempts can be verified by executing the login process with incorrect credentials and checking the lockout duration."
    },
    {
      "requirement_id": "KMU-004",
      "methods": ["Test"],
      "rationale": "File upload constraints (type and size) are verifiable by attempting to upload files of various formats and sizes and observing acceptance or rejection."
    },
    {
      "requirement_id": "KMU-005",
      "methods": ["Test"],
      "rationale": "Generation of a unique tracking number and its delivery via e‑mail can be observed by completing a submission and checking the received e‑mail content."
    },
    {
      "requirement_id": "KMU-006",
      "methods": ["Test"],
      "rationale": "The draft‑saving functionality and 30‑day retention can be verified by saving a partially completed application, waiting, and then resuming the session."
    },
    {
      "requirement_id": "KMU-007",
      "methods": ["İnceleme"],
      "rationale": "Compliance with WCAG 2.1 AA is assessed by reviewing design documents, UI code, and performing accessibility inspections."
    },
    {
      "requirement_id": "KMU-008",
      "methods": ["İnceleme"],
      "rationale": "Data residency requirements are verified by inspecting deployment configurations and documentation to ensure servers are located within Turkey."
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "WCAG 2.1 AA uyumluluğu - temel erişilebilirlik kontrolleri",
      "covers": [
        "KMU-007"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "",
      "test_inputs": "",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Uygulamanın ana sayfası bir ekran okuyucu (NVDA) ile açılır.",
          "expected": "Tüm görsel öğeler (buton, link, form alanı) için doğru aria‑label ve rol tanımları bulunur, ekran okuyucu bu bilgileri sesli olarak bildirir."
        },
        {
          "no": 2,
          "action": "Klavyeyle sayfa içinde gezinilir; tab tuşu ile bir sonraki odaklanabilir öğeye geçilir.",
          "expected": "Odak her seferinde yalnızca odaklanabilir öğeye (buton, link, giriş alanı) geçer, odak sırası mantıklı ve kaybolmaz."
        },
        {
          "no": 3,
          "action": "Renk kontrastı ölçüm aracı (axe‑core) ile tüm metin‑arka plan çiftlerinin kontrast oranı ölçülür.",
          "expected": "Tüm metin‑arka plan kombinasyonları en az 4.5:1 (normal metin) ve 3:1 (büyük metin) oranını sağlar."
        },
        {
          "no": 4,
          "action": "Form alanlarına hatalı veri girilir ve gönderim denemesi yapılır.",
          "expected": "Hata mesajları metin olarak sunulur, ekran okuyucu tarafından okunur ve ilgili form alanına odaklanır."
        },
        {
          "no": 5,
          "action": "Dinamik içerik (ör. modal pencere) açılır ve kapatılır.",
          "expected": "Modal açıldığında odak otomatik olarak modal içeriğine geçer ve aria‑modal=true özelliği bulunur; kapatıldığında odak önceki öğeye geri döner."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Konfigürasyon değişikliği gateway'i yeniden başlatmadan ve uçuşta olan istekleri düşürmeden uygulanır",
      "covers": [
        "SW-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Gateway çalışıyor, en az bir aktif istek (İstek A) işleme alınmış durumda.",
      "test_inputs": "",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "İstek A için bir HTTP GET isteği gönderilir ve yanıt beklenir.",
          "expected": "İstek A başarılı bir şekilde yanıt alır."
        },
        {
          "no": 2,
          "action": "Gateway'in konfigürasyonunda, örneğin timeout değeri 30 saniyeden 10 saniyeye düşürülür.",
          "expected": "Konfigürasyon değişikliği anında kaydedilir, gateway yeniden başlatılmaz."
        },
        {
          "no": 3,
          "action": "İstek B için aynı endpoint'e yeni bir HTTP GET isteği gönderilir.",
          "expected": "İstek B yeni timeout değerine göre işlenir ve yanıt alır."
        },
        {
          "no": 4,
          "action": "Gateway'in çalışma logunda restart mesajı aranır.",
          "expected": "Restart mesajı bulunmaz; gateway hiç yeniden başlatılmamıştır."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Her istek için izleme kimliği, istemci kimliği, uç nokta, yanıt kodu ve süre bilgisi yapılandırılmış günlükte kaydedilir",
      "covers": [
        "SW-007"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "Gateway yapılandırması günlük kaydı (logging) aktif ve gerekli alanları içerecek şekilde ayarlanmıştır.",
      "test_inputs": "",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Bir istemci kimliği “client-123” ile /api/v1/resource endpointine GET isteği gönderilir.",
          "expected": "İstek başarılı bir şekilde işlenir ve 200 yanıt kodu döner."
        },
        {
          "no": 2,
          "action": "Gateway'in log dosyası incelenir.",
          "expected": "Log kaydında bir satır bulunur; içinde izleme kimliği, istemci kimliği (client-123), uç nokta (/api/v1/resource), yanıt kodu (200) ve istek süresi (ms) yer alır."
        },
        {
          "no": 3,
          "action": "İstemci kimliği olmadan aynı endpoint’e bir istek daha gönderilir.",
          "expected": "İstek işlenir; log kaydında istemci kimliği alanı boş veya “unknown” olarak kaydedilir, diğer alanlar düzgünce bulunur."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Macro-averaged F1 score meets minimum threshold",
      "covers": [
        "AI-002"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model has been trained and a held-out evaluation set is available.",
      "test_inputs": "",
      "assumptions": "The evaluation set is representative of the production data distribution.",
      "steps": [
        {
          "no": 1,
          "action": "Run the model on the held-out evaluation set and collect predicted labels.",
          "expected": "Predictions are produced for all documents in the evaluation set."
        },
        {
          "no": 2,
          "action": "Calculate the macro-averaged F1 score from the predictions and ground‑truth labels.",
          "expected": "The computed macro‑averaged F1 score is reported."
        },
        {
          "no": 3,
          "action": "Compare the reported macro‑averaged F1 score with the required minimum of 0.90.",
          "expected": "The score is greater than or equal to 0.90, satisfying the requirement."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Recall parity between Turkish and English documents",
      "covers": [
        "AI-008"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "The model has been trained and a mixed-language evaluation set containing separate Turkish and English subsets is available.",
      "test_inputs": "",
      "assumptions": "Both language subsets have a sufficient number of samples to compute reliable recall values.",
      "steps": [
        {
          "no": 1,
          "action": "Run the model on the Turkish subset and compute recall for each class, then calculate the macro‑averaged recall for Turkish.",
          "expected": "Turkish macro‑averaged recall is obtained."
        },
        {
          "no": 2,
          "action": "Run the model on the English subset and compute recall for each class, then calculate the macro‑averaged recall for English.",
          "expected": "English macro‑averaged recall is obtained."
        },
        {
          "no": 3,
          "action": "Calculate the absolute difference between the Turkish and English macro‑averaged recall values.",
          "expected": "The difference is less than or equal to 5 percentage points, satisfying the requirement."
        }
      ]
    },
    {
      "id": "TC-3",
      "title": "Recall difference exceeds allowed limit (error case)",
      "covers": [
        "AI-008"
      ],
      "type": "Hata",
      "priority": "Düşük",
      "preconditions": "The model has been trained and a mixed-language evaluation set is available.",
      "test_inputs": "",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Intentionally modify the model or evaluation data to create a scenario where Turkish recall is 0.80 and English recall is 0.70.",
          "expected": "Recall values are set as specified."
        },
        {
          "no": 2,
          "action": "Calculate the absolute difference between the two recall values.",
          "expected": "The difference is 10 percentage points, which exceeds the allowed 5‑point limit."
        },
        {
          "no": 3,
          "action": "Verify that the system flags a compliance violation.",
          "expected": "The system reports a failure of requirement AI-008."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Casualty data encryption verification",
      "covers": [
        "MED-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Uygulama kurulmuş ve bir test kullanıcısı oturum açmış durumda.",
      "test_inputs": "",
      "assumptions": "Cihazda veri depolama fonksiyonu çalışır; veri ekleme API’si kullanılabilir.",
      "steps": [
        {
          "no": 1,
          "action": "Uygulama üzerinden yeni bir yaralanma kaydı (örnek veri) girilir ve kaydedilir.",
          "expected": "Veri cihazın depolama alanına yazılır."
        },
        {
          "no": 2,
          "action": "Depolanan dosyanın ham (plaintext) içeriği cihazın dosya sisteminden okunmaya çalışılır.",
          "expected": "Dosya içeriği okunamaz veya okunmuşsa şifreli (görünür karakterler anlamsız) olur; AES‑256 şifreleme kullanıldığı kanıtlanır."
        },
        {
          "no": 3,
          "action": "Uygulama üzerinden aynı yaralanma kaydı görüntülenir.",
          "expected": "Uygulama şifreyi çözer ve orijinal veri ekranda doğru şekilde gösterilir."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Battery endurance minimum 8‑hour test",
      "covers": [
        "MED-008"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "Tablet tamamen şarj edilmiş ve tanımlı kullanım profiline uygun olarak yapılandırılmıştır.",
      "test_inputs": "",
      "assumptions": "Tanımlı kullanım profili: sürekli ekran aktif, veri giriş/çıkış, radyo (Wi‑Fi) etkin, periyodik GPS sorgusu.",
      "steps": [
        {
          "no": 1,
          "action": "Tablet üzerinde uygulama başlatılır ve kullanım profiline uygun senaryolar (ekran dokunma, veri kaydı, ağ iletişimi) otomatik olarak çalıştırılır.",
          "expected": "Uygulama sorunsuz çalışır, batarya seviyesi %100'den azalır."
        },
        {
          "no": 2,
          "action": "Batarya seviyesi %0’a ulaşana kadar senaryo çalıştırılmaya devam edilir.",
          "expected": "Tablet kapanmadan önce batarya seviyesi %0’a yaklaşır."
        },
        {
          "no": 3,
          "action": "Kapanma zamanı kaydedilir.",
          "expected": "Tablet en az 8 saat (480 dakika) çalışma süresi sağlar."
        }
      ]
    },
    {
      "id": "TC-3",
      "title": "Battery endurance below minimum threshold",
      "covers": [
        "MED-008"
      ],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "Tablet %50 şarjlı ve yüksek parlaklıkta, Wi‑Fi ve Bluetooth sürekli açık.",
      "test_inputs": "",
      "assumptions": "Kullanım profili aynı kalır, ancak cihaz daha düşük başlangıç şarjına sahiptir.",
      "steps": [
        {
          "no": 1,
          "action": "Uygulama aynı kullanım profiliyle çalıştırılır.",
          "expected": "Cihaz %50 şarjla başlar."
        },
        {
          "no": 2,
          "action": "Batarya %0’a ulaşmadan cihaz kapanır.",
          "expected": "Toplam çalışma süresi 8 saatten az olur, gereksinim karşılanmaz."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Document classification into a single category with valid confidence",
      "covers": [
        "AI-001"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification service is deployed and reachable.",
      "test_inputs": "A well‑formed document text belonging clearly to category \"Finance\".",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Submit the document to the /classify endpoint.",
          "expected": "The response contains a field `category` with one of the 12 allowed category identifiers and a field `confidence` with a numeric value."
        },
        {
          "no": 2,
          "action": "Verify that `confidence` is greater than or equal to 0 and less than or equal to 1.",
          "expected": "The confidence value satisfies 0 ≤ confidence ≤ 1."
        },
        {
          "no": 3,
          "action": "Verify that only one `category` is returned.",
          "expected": "Exactly one category identifier is present in the response."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Boundary confidence score routing at 0.60",
      "covers": [
        "AI-003"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "The service is operational and the routing queue is empty.",
      "test_inputs": "A document crafted to produce a classification confidence of exactly 0.60.",
      "assumptions": "The service can be configured or the test document can be selected such that the confidence score returns exactly 0.60.",
      "steps": [
        {
          "no": 1,
          "action": "Submit the document to the /classify endpoint.",
          "expected": "The response includes `confidence` = 0.60 and a `category` value."
        },
        {
          "no": 2,
          "action": "Check the system's routing outcome for this request.",
          "expected": "The document is automatically classified (not sent to the human review queue) because the confidence is not below 0.60."
        }
      ]
    },
    {
      "id": "TC-3",
      "title": "Routing to human review when confidence is below threshold",
      "covers": [
        "AI-003"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "The service is running and the human review queue is operational.",
      "test_inputs": "A document that yields a confidence score of 0.45.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Submit the document to the /classify endpoint.",
          "expected": "The response contains `confidence` = 0.45."
        },
        {
          "no": 2,
          "action": "Inspect the routing result of the request.",
          "expected": "The document is placed in the human review queue and no automatic category is returned."
        }
      ]
    },
    {
      "id": "TC-4",
      "title": "Providing top three contributing passages for a classification",
      "covers": [
        "AI-007"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "A document that can be confidently classified (confidence ≥ 0.80) is available.",
      "test_inputs": "Document text about \"Medical Research\".",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Submit the document to the /classify endpoint with the request parameter `explain=true`.",
          "expected": "The response includes a `top_passages` array containing exactly three text snippets."
        },
        {
          "no": 2,
          "action": "Verify that each passage is a substring of the original document.",
          "expected": "All three passages appear in the submitted document text."
        },
        {
          "no": 3,
          "action": "Confirm that the passages are ordered by their contribution weight (highest first).",
          "expected": "The first passage has the highest contribution, followed by the second and third."
        }
      ]
    },
    {
      "id": "TC-5",
      "title": "Error handling when service receives an empty document",
      "covers": [
        "AI-001",
        "AI-007"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "The classification service endpoint is reachable.",
      "test_inputs": "An empty string as document content.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Submit the empty document to the /classify endpoint.",
          "expected": "The service returns an error response with HTTP status 400 and a message indicating that the document is empty."
        },
        {
          "no": 2,
          "action": "Verify that no `category`, `confidence`, or `top_passages` fields are present in the error response.",
          "expected": "The response body contains only error details."
        }
      ]
    }
  ]
}

{
  "test_cases": [
